"""Skandamata `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys

MEASURES = ("hit@1", "recall@5", "precision@5", "mrr", "ndcg@10")


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    d = r["dataset"]
    b = d["behaviours"]
    out = [
        "<!-- Generated by packages/sati/sati/respond/report.py from the training workflow. Do not edit by hand. -->\n",
        "# Skandamata v0 — from observed behaviour to the mitigations that defend against it\n",
        f"**{d['name']}**: {d['mitigations']} mitigations. Behaviours split **by source**: train {b['train']:,}, "
        f"validation {b['validation']:,}, test {b['test']:,}. The test behaviours are written about "
        f"{d['test_sources_unseen']} groups, malware families, tools and campaigns never seen in training. Each "
        f"behaviour has {d['right_mitigations_per_behaviour']} right mitigations on average: the ones ATT&CK links "
        "to its technique.\n",
        "| Recommender | Hit@1 | Recall@5 | Precision@5 | MRR | nDCG@10 |",
        "|---|---:|---:|---:|---:|---:|",
    ]
    for name, m in r["test"].items():
        label = f"**{name}**" if name.startswith("skandamata") else name
        out.append(f"| {label} | " + " | ".join(f"{m[k]:.3f}" for k in MEASURES) + " |")
    fused = ""
    if "fusion_weight_by_validation" in r:
        fused = f" Fusion weight on Skandamata, chosen on validation behaviours: {r['fusion_weight_by_validation']:.2f}."
    out += ["", f"Epoch chosen on validation behaviours: {r['best_epoch_by_validation']}.{fused}\n",
            "## Examples (test behaviours, unedited)\n"]
    for e in r["examples"]:
        out.append(f"- **Behaviour:** {e['behaviour']}\n  **ATT&CK says:** {', '.join(e['expected'])}\n"
                   f"  **Skandamata recommends:** {', '.join(e['recommended'])}")
    out += [
        "",
        "## How to read this\n",
        "- **Popularity** gives everyone the same list. A few mitigations, such as auditing and user training, apply "
        "to most techniques, so it is a hard bar. A model that does not clear it has learned nothing about the "
        "behaviour.",
        "- Skandamata **recommends**; it does not act. In Sati, a recommended response is an action proposal that "
        "Dharma must authorise (rule 2).",
        "- Includes MITRE ATT&CK content, © The MITRE Corporation, used under its royalty-free licence. Designed, "
        "written and trained by an AI assistant under the owner's direction "
        "([adr/RealDataModels](../../adr/RealDataModels.md)).",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
